function setMessage(text,isError=false){const el=document.querySelector('#noorCloudMessage');if(el){el.textContent=text||'';el.classList.toggle('error',Boolean(isError));}}
function setSyncState(text){const el=document.querySelector('#noorSyncState');if(el)el.textContent=text;const offline=document.querySelector('#offlineText');if(offline)offline.textContent=user?text:'Local-first workspace';}
function toast(text){const t=document.querySelector('#toast');if(t){t.textContent=text;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400);}}
function authHeaders(extra={}){return {'apikey':SUPABASE_KEY,'Authorization':`Bearer ${session?.access_token||SUPABASE_KEY}`,...extra};}
function saveSession(s){session=s||null;user=s?.user||null;if(session)localStorage.setItem(AUTH_KEY,JSON.stringify(session));else localStorage.removeItem(AUTH_KEY);window.NOORCloudUser=user?{id:user.id,email:user.email,name:user.user_metadata?.display_name||user.email?.split('@')[0]||'NOOR user'}:null;}
function loadSavedSession(){
  try{const raw=localStorage.getItem(AUTH_KEY);if(raw){const s=JSON.parse(raw);if(s?.access_token&&s?.refresh_token){saveSession(s);return;}}}catch{}
  try{const raw=localStorage.getItem(LEGACY_AUTH_KEY);if(raw){const s=JSON.parse(raw);if(s?.access_token&&s?.refresh_token){saveSession(s);localStorage.removeItem(LEGACY_AUTH_KEY);}}}catch{}
}
async function authRequest(path,{method='POST',body}={}){
  const res=await fetch(`${SUPABASE_URL}/auth/v1${path}`,{method,headers:{'apikey':SUPABASE_KEY,'Content-Type':'application/json',...(session?.access_token?{'Authorization':`Bearer ${session.access_token}`}:{})},body:body?JSON.stringify(body):undefined});
  let data=null;try{data=await res.json();}catch{}
  if(!res.ok)throw new Error(data?.msg||data?.message||data?.error_description||`Authentication failed (${res.status}).`);return data;
}
async function ensureFreshSession(){
  if(!session?.refresh_token)return false;const expiresAt=Number(session.expires_at||0)*1000;if(expiresAt&&expiresAt-Date.now()>90000)return true;
  try{const data=await authRequest('/token?grant_type=refresh_token',{body:{refresh_token:session.refresh_token}});saveSession({...data,expires_at:data.expires_at||Math.floor(Date.now()/1000)+Number(data.expires_in||3600)});return true;}catch{saveSession(null);renderAuthState();return false;}
}
async function api(path,{method='GET',body,headers={}}={}){
  if(user)await ensureFreshSession();const res=await fetch(`${SUPABASE_URL}${path}`,{method,headers:authHeaders({'Content-Type':'application/json',...headers}),body:body===undefined?undefined:JSON.stringify(body)});
  if(res.status===204)return null;const text=await res.text();let data=text;try{data=text?JSON.parse(text):null;}catch{}
  if(!res.ok)throw new Error(data?.message||data?.error_description||data?.msg||`Cloud request failed (${res.status}).`);return data;
}
async function rest(table,query='',opts={}){return api(`/rest/v1/${table}${query?`?${query}`:''}`,opts);}
async function rpc(name,body){return api(`/rest/v1/rpc/${name}`,{method:'POST',body});}
function eq(name,value){return `${encodeURIComponent(name)}=eq.${encodeURIComponent(value)}`;}
function and(parts){return parts.filter(Boolean).join('&');}
async function selectOne(table,filters){const rows=await rest(table,and([...filters,'select=*','limit=1']));return rows?.[0]||null;}
async function insertRow(table,row){const rows=await rest(table,'select=*',{method:'POST',headers:{'Prefer':'return=representation'},body:row});return rows?.[0]||null;}
async function patchRows(table,filters,row){return rest(table,and([...filters,'select=*']),{method:'PATCH',headers:{'Prefer':'return=representation'},body:row});}
async function deleteRows(table,filters){return rest(table,and(filters),{method:'DELETE',headers:{'Prefer':'return=minimal'}});}

