function openAccount(){ensureUI();document.querySelector('#noorAccountDialog').showModal();renderAuthState();renderVaultState();}
function renderAuthState(){if(!document.querySelector('#noorAccountDialog'))return;document.querySelector('#cloudSignedOut').hidden=Boolean(user);document.querySelector('#cloudSignedIn').hidden=!user;const dot=document.querySelector('#noorAccountBtn .cloud-dot');dot?.classList.toggle('on',Boolean(user&&vaultUnlocked()));dot?.classList.toggle('locked',Boolean(user&&!vaultUnlocked()));const label=document.querySelector('#noorAccountBtn .account-label');if(label)label.textContent=user?(vaultUnlocked()?'Vault':'Locked'):'Account';if(user){document.querySelector('#cloudUserName').textContent=user.user_metadata?.display_name||user.email?.split('@')[0]||'NOOR user';document.querySelector('#cloudUserEmail').textContent=user.email||'';}}
function renderVaultState(){if(!document.querySelector('#vaultSummary'))return;const has=Boolean(vaultProfile),unlocked=vaultUnlocked();document.querySelector('#vaultSetupForm').hidden=has;document.querySelector('#vaultUnlockForm').hidden=!has||unlocked;document.querySelector('#vaultRecoverWrap').hidden=!has||unlocked;document.querySelector('#vaultOnly').hidden=!unlocked;document.querySelector('#lockVault').hidden=!unlocked;document.querySelector('#vaultSummary').innerHTML=unlocked?'<span class="vault-good">Unlocked.</span> Scientific records and files are encrypted in this browser before cloud upload.':has?'<span class="vault-warn">Locked.</span> Sign-in alone cannot decrypt research data.':'No vault exists yet. Create one before uploading confidential research.';document.querySelector('#secPayload').textContent=unlocked?'AES-256-GCM client-side':'Locked';renderAuthState();if(unlocked)setSyncState('Encrypted vault · ready');else setSyncState(user?'Encrypted vault · locked':'Local-first workspace');}

async function signIn(ev){ev.preventDefault();setMessage('Signing in…');try{const data=await authRequest('/token?grant_type=password',{body:{email:document.querySelector('#cloudEmail').value.trim(),password:document.querySelector('#cloudPassword').value}});saveSession({...data,expires_at:data.expires_at||Math.floor(Date.now()/1000)+Number(data.expires_in||3600)});await afterAuth();setMessage(vaultProfile?'Signed in. Unlock the research vault to sync.':'Signed in. Create your encrypted research vault before syncing.');}catch(e){setMessage(e.message,true);}}
async function signUp(ev){ev.preventDefault();setMessage('Creating account…');try{const email=document.querySelector('#cloudNewEmail').value.trim(),password=document.querySelector('#cloudNewPassword').value,name=document.querySelector('#cloudName').value.trim();const redirect=encodeURIComponent(location.origin+location.pathname);const data=await authRequest(`/signup?redirect_to=${redirect}`,{body:{email,password,data:{display_name:name}}});if(data?.access_token){saveSession({...data,expires_at:data.expires_at||Math.floor(Date.now()/1000)+Number(data.expires_in||3600)});await afterAuth();setMessage('Account created. Create the encrypted vault next.');}else setMessage('Account created. Confirm your email, then sign in.');}catch(e){setMessage(e.message,true);}}
async function signOut(){try{if(session?.access_token)await authRequest('/logout',{body:{}});}catch{}saveSession(null);clearVault();workspaceKeys.clear();directExperimentKeys.clear();workspaces=[];activeWorkspace=null;vaultProfile=null;if(syncTimer)clearInterval(syncTimer);renderAuthState();renderVaultState();setMessage('Signed out. Local notebook remains on this device.');}
async function afterAuth(){user=session?.user||user;window.NOORCloudUser=user?{id:user.id,email:user.email,name:user.user_metadata?.display_name||user.email?.split('@')[0]||'NOOR user'}:null;await Promise.all([loadVaultProfile(),loadWorkspaces()]);renderAuthState();renderVaultState();await acceptInviteParams();scheduleSync();}

async function loadVaultProfile(){if(!user)return;vaultProfile=await selectOne('vault_profiles',[eq('user_id',user.id)]);}
async function setupVault(ev){ev.preventDefault();const p=document.querySelector('#vaultSetupPass').value,c=document.querySelector('#vaultSetupConfirm').value;if(p!==c)return setMessage('Vault passphrases do not match.',true);try{const created=await createVaultProfile(user.id,p);vaultProfile=await insertRow('vault_profiles',created.profile);document.querySelector('#vaultRecoveryText').textContent=created.recovery;document.querySelector('#vaultRecoveryDisplay').hidden=false;document.querySelector('#vaultSetupForm').reset();renderVaultState();await ensureWorkspaceKey(activeWorkspace);setMessage('Encrypted vault created. Save the recovery code before relying on cloud encryption.');}catch(e){setMessage(e.message,true);}}
async function unlockVault(ev){ev.preventDefault();try{await unlockVaultProfile(user.id,vaultProfile,document.querySelector('#vaultUnlockPass').value);document.querySelector('#vaultUnlockForm').reset();workspaceKeys.clear();directExperimentKeys.clear();renderVaultState();await ensureWorkspaceKey(activeWorkspace);await acceptInviteParams();setMessage('Vault unlocked. Encrypting/syncing eligible cloud records…');await syncNow();}catch(e){setMessage(e.message,true);}}
async function recoverVault(ev){ev.preventDefault();try{const patch=await recoverVaultProfile(user.id,vaultProfile,document.querySelector('#vaultRecoveryCode').value,document.querySelector('#vaultRecoveryNewPass').value);const rows=await patchRows('vault_profiles',[eq('user_id',user.id)],patch);vaultProfile=rows?.[0]||{...vaultProfile,...patch};document.querySelector('#vaultRecoverForm').reset();renderVaultState();setMessage('Vault recovered and re-keyed with the new passphrase.');await syncNow();}catch(e){setMessage(e.message,true);}}

async function loadWorkspaces(){if(!user)return;const rows=await rest('workspace_members',`select=workspace_id,role,joined_at,workspaces(id,name,owner_id)&order=joined_at.asc`);workspaces=(rows||[]).map(x=>({id:x.workspace_id,role:x.role,name:x.workspaces?.name||'Workspace',ownerId:x.workspaces?.owner_id}));if(!workspaces.length){const w=await insertRow('workspaces',{name:'My NOOR',owner_id:user.id});await insertRow('workspace_members',{workspace_id:w.id,user_id:user.id,role:'owner'});workspaces=[{id:w.id,name:w.name,ownerId:w.owner_id,role:'owner'}];}const remembered=localStorage.getItem('noor.activeWorkspace');activeWorkspace=workspaces.find(w=>w.id===remembered)||workspaces[0]||null;if(activeWorkspace)localStorage.setItem('noor.activeWorkspace',activeWorkspace.id);const sel=document.querySelector('#noorWorkspaceSelect');if(sel)sel.innerHTML=workspaces.map(w=>`<option value="${w.id}" ${w.id===activeWorkspace?.id?'selected':''}>${esc(w.name)} · ${esc(w.role)}</option>`).join('');}
async function createWorkspace(){if(!vaultUnlocked())return setMessage('Unlock the vault first.',true);const name=prompt('Lab workspace name');if(!name?.trim())return;try{const w=await insertRow('workspaces',{name:name.trim(),owner_id:user.id});await insertRow('workspace_members',{workspace_id:w.id,user_id:user.id,role:'owner'});await loadWorkspaces();activeWorkspace=workspaces.find(x=>x.id===w.id)||activeWorkspace;localStorage.setItem('noor.activeWorkspace',w.id);await ensureWorkspaceKey(activeWorkspace);setMessage(`Created ${name.trim()} with a new encrypted workspace key.`);await syncNow();}catch(e){setMessage(e.message,true);}}
async function ensureWorkspaceKey(workspace){if(!workspace||!vaultUnlocked())throw new Error('Vault is locked.');if(workspaceKeys.has(workspace.id))return workspaceKeys.get(workspace.id);const row=await selectOne('workspace_key_wrappers',[eq('workspace_id',workspace.id),eq('user_id',user.id)]);const wrapKey=await masterWrapKey();if(row){const raw=await unwrapRawKey(row.wrapped_key,row.nonce,wrapKey,`workspace:${workspace.id}:user:${user.id}`);workspaceKeys.set(workspace.id,raw);return raw;}if(['owner','admin'].includes(workspace.role)){const raw=randomBytes(32);const wrapped=await wrapRawKey(raw,wrapKey,`workspace:${workspace.id}:user:${user.id}`);await insertRow('workspace_key_wrappers',{workspace_id:workspace.id,user_id:user.id,wrapped_key:wrapped.ciphertext,nonce:wrapped.nonce,crypto_version:CRYPTO_VERSION});workspaceKeys.set(workspace.id,raw);return raw;}throw new Error('This workspace has no key for your account. Ask an owner/admin to send a new secure invite.');}
async function experimentKeyForRow(row){if(directExperimentKeys.has(row.id))return directExperimentKeys.get(row.id);const ws=workspaces.find(w=>w.id===row.workspace_id);if(ws){const wk=await ensureWorkspaceKey(ws);return deriveExperimentKey(wk,row.local_id);}const wrapper=await selectOne('experiment_key_wrappers',[eq('experiment_id',row.id),eq('user_id',user.id)]);if(!wrapper)throw new Error('No experiment decryption key is available for this shared record.');const raw=await unwrapRawKey(wrapper.wrapped_key,wrapper.nonce,await masterWrapKey(),`experiment:${row.id}:user:${user.id}`);directExperimentKeys.set(row.id,raw);return raw;}
async function experimentKeyForLocal(exp,workspace){const wk=await ensureWorkspaceKey(workspace);return deriveExperimentKey(wk,exp.id);}

function secureInviteURL(kind,token,secret){const url=new URL(location.href);url.search='';url.hash='';url.searchParams.set(kind,token);url.hash=new URLSearchParams({noorKey:b64u(secret)}).toString();return url.toString();}
async function copyText(text){try{await navigator.clipboard.writeText(text);setMessage('Secure invite link copied to clipboard.');}catch{setMessage(`Secure invite link: ${text}`);}}
async function createWorkspaceInvite(ev){ev.preventDefault();if(!vaultUnlocked())return setMessage('Unlock the vault first.',true);if(!activeWorkspace)return;try{const email=document.querySelector('#workspaceInviteEmail').value.trim().toLowerCase(),role=document.querySelector('#workspaceInviteRole').value,wk=await ensureWorkspaceKey(activeWorkspace);const existing=await selectOne('workspace_invites',[eq('workspace_id',activeWorkspace.id),`email=eq.${encodeURIComponent(email)}`]);let inv=existing;if(existing){const rows=await patchRows('workspace_invites',[eq('id',existing.id)],{role,invited_by:user.id,accepted_at:null});inv=rows?.[0]||existing;}else inv=await insertRow('workspace_invites',{workspace_id:activeWorkspace.id,email,role,invited_by:user.id});const secret=randomBytes(32);const pkg=await wrapWithSecret(wk,secret,`workspace-invite:${inv.token}`);const old=await selectOne('workspace_key_invites',[eq('invite_token',inv.token)]);if(old)await patchRows('workspace_key_invites',[eq('invite_token',inv.token)],{workspace_id:activeWorkspace.id,encrypted_workspace_key:pkg.ciphertext,nonce:pkg.nonce,crypto_version:CRYPTO_VERSION,created_by:user.id,expires_at:new Date(Date.now()+7*86400000).toISOString()});else await insertRow('workspace_key_invites',{invite_token:inv.token,workspace_id:activeWorkspace.id,encrypted_workspace_key:pkg.ciphertext,nonce:pkg.nonce,crypto_version:CRYPTO_VERSION,created_by:user.id,expires_at:new Date(Date.now()+7*86400000).toISOString()});await copyText(secureInviteURL('workspaceInvite',inv.token,secret));ev.target.reset();}catch(e){setMessage(e.message,true);}}
async function createExperimentInvite(ev){ev.preventDefault();if(!vaultUnlocked())return setMessage('Unlock the vault first.',true);try{const localId=document.querySelector('#shareExperimentId').value;let exp=await get('experiments',localId);if(!exp)return setMessage('Experiment not found.',true);if(!exp.cloudId){await syncNow({silent:true});exp=await get('experiments',localId);}if(!exp?.cloudId)return setMessage('Encrypted sync this experiment before sharing it.',true);const ws=workspaces.find(w=>w.id===exp.workspaceId)||activeWorkspace;const expKey=await experimentKeyForLocal(exp,ws);const email=document.querySelector('#experimentInviteEmail').value.trim().toLowerCase(),permission=document.querySelector('#experimentInvitePermission').value;const existing=await selectOne('experiment_invites',[eq('experiment_id',exp.cloudId),`email=eq.${encodeURIComponent(email)}`]);let inv=existing;if(existing){const rows=await patchRows('experiment_invites',[eq('id',existing.id)],{permission,invited_by:user.id,accepted_at:null});inv=rows?.[0]||existing;}else inv=await insertRow('experiment_invites',{experiment_id:exp.cloudId,email,permission,invited_by:user.id});const secret=randomBytes(32);const pkg=await wrapWithSecret(expKey,secret,`experiment-invite:${inv.token}`);const old=await selectOne('experiment_key_invites',[eq('invite_token',inv.token)]);if(old)await patchRows('experiment_key_invites',[eq('invite_token',inv.token)],{experiment_id:exp.cloudId,encrypted_experiment_key:pkg.ciphertext,nonce:pkg.nonce,crypto_version:CRYPTO_VERSION,created_by:user.id,expires_at:new Date(Date.now()+7*86400000).toISOString()});else await insertRow('experiment_key_invites',{invite_token:inv.token,experiment_id:exp.cloudId,encrypted_experiment_key:pkg.ciphertext,nonce:pkg.nonce,crypto_version:CRYPTO_VERSION,created_by:user.id,expires_at:new Date(Date.now()+7*86400000).toISOString()});await copyText(secureInviteURL('experimentInvite',inv.token,secret));ev.target.reset();}catch(e){setMessage(e.message,true);}}
async function acceptInviteParams(){if(!user||!vaultUnlocked())return;const url=new URL(location.href),fragment=new URLSearchParams(url.hash.replace(/^#/,'')),secretText=fragment.get('noorKey');const workspaceToken=url.searchParams.get('workspaceInvite'),experimentToken=url.searchParams.get('experimentInvite');if(!workspaceToken&&!experimentToken)return;if(!secretText)return setMessage('Secure invite key is missing from the link. Ask the inviter to resend the full link.',true);let secret;try{secret=unb64u(secretText);if(secret.length!==32)throw 0;}catch{return setMessage('Secure invite key is invalid.',true);}try{if(workspaceToken){const inv=await selectOne('workspace_invites',[eq('token',workspaceToken)]);if(!inv)throw new Error('Workspace invite was not found or has expired.');const pkg=await selectOne('workspace_key_invites',[eq('invite_token',workspaceToken)]);if(!pkg)throw new Error('Encrypted workspace key package is missing.');await rpc('accept_workspace_invite',{invite_token:workspaceToken});await loadWorkspaces();const wk=await unwrapWithSecret(pkg.encrypted_workspace_key,pkg.nonce,secret,`workspace-invite:${workspaceToken}`);const wrapped=await wrapRawKey(wk,await masterWrapKey(),`workspace:${pkg.workspace_id}:user:${user.id}`);const existing=await selectOne('workspace_key_wrappers',[eq('workspace_id',pkg.workspace_id),eq('user_id',user.id)]);if(existing)await patchRows('workspace_key_wrappers',[eq('workspace_id',pkg.workspace_id),eq('user_id',user.id)],{wrapped_key:wrapped.ciphertext,nonce:wrapped.nonce,crypto_version:CRYPTO_VERSION});else await insertRow('workspace_key_wrappers',{workspace_id:pkg.workspace_id,user_id:user.id,wrapped_key:wrapped.ciphertext,nonce:wrapped.nonce,crypto_version:CRYPTO_VERSION});workspaceKeys.set(pkg.workspace_id,wk);await deleteRows('workspace_key_invites',[eq('invite_token',workspaceToken)]);url.searchParams.delete('workspaceInvite');setMessage('Secure lab workspace invite accepted.');}
    if(experimentToken){const inv=await selectOne('experiment_invites',[eq('token',experimentToken)]);if(!inv)throw new Error('Experiment invite was not found or has expired.');const pkg=await selectOne('experiment_key_invites',[eq('invite_token',experimentToken)]);if(!pkg)throw new Error('Encrypted experiment key package is missing.');await rpc('accept_experiment_invite',{invite_token:experimentToken});const ek=await unwrapWithSecret(pkg.encrypted_experiment_key,pkg.nonce,secret,`experiment-invite:${experimentToken}`);const wrapped=await wrapRawKey(ek,await masterWrapKey(),`experiment:${pkg.experiment_id}:user:${user.id}`);const existing=await selectOne('experiment_key_wrappers',[eq('experiment_id',pkg.experiment_id),eq('user_id',user.id)]);if(existing)await patchRows('experiment_key_wrappers',[eq('experiment_id',pkg.experiment_id),eq('user_id',user.id)],{wrapped_key:wrapped.ciphertext,nonce:wrapped.nonce,crypto_version:CRYPTO_VERSION});else await insertRow('experiment_key_wrappers',{experiment_id:pkg.experiment_id,user_id:user.id,wrapped_key:wrapped.ciphertext,nonce:wrapped.nonce,crypto_version:CRYPTO_VERSION});directExperimentKeys.set(pkg.experiment_id,ek);await deleteRows('experiment_key_invites',[eq('invite_token',experimentToken)]);url.searchParams.delete('experimentInvite');setMessage('Secure experiment invite accepted.');}
    url.hash='';history.replaceState({},'',url.toString());await loadWorkspaces();await syncNow();}catch(e){setMessage(e.message,true);}}

function stripCloud(obj){const x=cleanJSON(obj);for(const k of ['cloudId','cloudUpdatedAt','workspaceId'])delete x[k];return x;}
async function projectKey(workspace){return deriveKey(await ensureWorkspaceKey(workspace),'project-payload','NOOR-workspace-data-v1');}
async function genericKey(workspace,store,record){if(record.experimentId){const exp=await get('experiments',record.experimentId);if(exp)return experimentKeyForLocal(exp,workspace);}return deriveKey(await ensureWorkspaceKey(workspace),`store:${store}`,'NOOR-workspace-data-v1');}
