function legacyProject(row){return {id:row.local_id||`cloud_${row.id}`,cloudId:row.id,workspaceId:row.workspace_id,cloudUpdatedAt:row.updated_at,name:row.name,title:row.name,description:row.description||'',status:row.status||'',blocker:row.blocker||'',createdAt:row.created_at,updatedAt:row.updated_at};}
