async function secureProjectRow(local,workspace,remote){const payload=await encryptProject(local,workspace);let saved;if(remote){const rows=await patchRows('projects',[eq('id',remote.id)],{...payload,updated_by:user.id});saved=rows?.[0]||remote;}else saved=await insertRow('projects',{...payload,updated_by:user.id});await put('projects',{...local,cloudId:saved.id,workspaceId:workspace.id,cloudUpdatedAt:saved.updated_at});return saved;}
