async function syncNow({silent=false}={}){if(!user)return;if(!vaultUnlocked()){if(!silent)setMessage('Unlock the encrypted vault before cloud sync.',true);return;}if(syncing)return;syncing=true;const stats={pushed:0,pulled:0,migrated:0,conflicts:0,files:0,largeFiles:0,legacyShared:0};try{if(!activeWorkspace)await loadWorkspaces();setSyncState('Encrypted sync…');await ensureWorkspaceKey(activeWorkspace);await syncProjects(activeWorkspace,stats);await syncExperiments(activeWorkspace,stats);await syncRevisions(activeWorkspace,stats);await syncGeneric(activeWorkspace,stats);await syncFiles(activeWorkspace,stats);await syncSharedExperiments(stats);window.dispatchEvent(new CustomEvent('noor:cloud-pull'));setSyncState(`Encrypted sync · ${new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}`);if(!silent){let msg=`Encrypted sync complete: ${stats.pushed} pushed, ${stats.pulled} pulled`;if(stats.migrated)msg+=`, ${stats.migrated} legacy plaintext record${stats.migrated===1?'':'s'} encrypted`;if(stats.conflicts)msg+=`, ${stats.conflicts} conflict${stats.conflicts===1?'':'s'} held`;if(stats.largeFiles)msg+=`. ${stats.largeFiles} file(s) over 25 MB stayed local`;setMessage(msg);toast('Encrypted sync complete');}}catch(e){setSyncState('Encrypted sync error');if(!silent)setMessage(e.message,true);console.error('NOOR encrypted sync:',e);}finally{syncing=false;}}
function scheduleSync(){if(syncTimer)clearInterval(syncTimer);syncTimer=setInterval(()=>{if(user&&vaultUnlocked()&&navigator.onLine)syncNow({silent:true});},60000);}
function wireShareButtons(){const list=document.querySelector('#experimentList');if(!list)return;const add=async()=>{for(const card of list.querySelectorAll('.record-card')){if(card.querySelector('[data-share-exp]'))continue;const edit=card.querySelector('[data-edit-exp]');if(!edit)continue;const b=document.createElement('button');b.type='button';b.dataset.shareExp=edit.dataset.editExp;b.textContent='Share';b.onclick=async()=>{if(!user)return openAccount();if(!vaultUnlocked()){openAccount();return setMessage('Unlock the vault before creating a secure share.',true);}const exp=await get('experiments',b.dataset.shareExp);document.querySelector('#shareExperimentId').value=exp.id;document.querySelector('#shareExperimentName').textContent=exp.title||'Experiment';document.querySelector('#noorSharePanel').classList.remove('hidden');openAccount();};card.querySelector('.record-actions')?.insertBefore(b,card.querySelector('.record-actions')?.firstChild);}};new MutationObserver(add).observe(list,{childList:true,subtree:true});add();}
async function init(){ensureStyles();ensureUI();loadSavedSession();renderAuthState();renderVaultState();if(user){try{await afterAuth();}catch(e){setMessage(e.message,true);}}wireShareButtons();window.addEventListener('online',()=>{if(user&&vaultUnlocked())syncNow({silent:true});});window.addEventListener('focus',()=>{if(user&&vaultUnlocked())syncNow({silent:true});});window.addEventListener('noor:vault-lock',()=>{workspaceKeys.clear();directExperimentKeys.clear();renderVaultState();});}
if(typeof document!=='undefined'){if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(init,250));else setTimeout(init,250);}
